# 040 · CARRILES · imagen de elección en urolitiasis
S("carriles", "RM-NEF-040", "Ante sospecha de urolitiasis en el adulto, la tomografía helicoidal sin contraste es el estudio de elección",
  "Urología · imagen en el cólico renoureteral",
  ("Urolitiasis", ["Cólico lumbar que irradia a la fosa ilíaca y los genitales, con hematuria, náuseas y agitación.", "La imagen confirma, localiza y mide el cálculo."]),
  ("Pregunta de estudio", ["¿Cuál es el examen preferencial ante la sospecha de urolitiasis?"]),
  ["La tomografía sin contraste (de baja dosis) tiene sensibilidad y especificidad de 95 a 98 %, ve cálculos de cualquier composición (también ácido úrico) y mide el tamaño y la densidad en unidades Hounsfield.",
   "Ecografía renal: primera opción en la embarazada y el niño, y para seguimiento; en urgencias, empezar por ella redujo la radiación sin más desenlaces graves (Smith-Bindman 2014), pero omite cálculos pequeños.",
   "La radiografía simple solo ve cálculos radioopacos (sensibilidad de 50 a 60 %). La pielografía retrógrada y la cistoscopía son invasivas y no son de primera línea.",
   "Alerta: fiebre con obstrucción o anuria exige derivación urgente (sonda doble J o nefrostomía)."],
  "AUA, Medical Management of Kidney Stones (J Urol 2026); Smith-Bindman R et al., Ecografía vs. tomografía en sospecha de nefrolitiasis (N Engl J Med 2014); " + CW + ".",
  op=("¿Examen preferencial?", ["Sí: más sensible y específico", "No: de elección en la embarazada y el niño", "No: solo ve cálculos radioopacos", "No: invasiva, no es de primera línea", "No: invasiva, no es de primera línea"],
      {0: "Tomografía computarizada", 1: "Ecografía renal", 2: "Radiografía simple de abdomen", 3: "Pielografía retrógrada", 4: "Cistoscopía"}),
  d=dict(rotulo="Qué estudio se pide en cada situación", carriles=["Adulto con sospecha de urolitiasis", "Embarazada, niño o seguimiento", "No son de primera línea"],
         pasos=[(0, "Tomografía sin contraste", "Sensibilidad de 95 a 98 %; detecta todo tipo de cálculo y diagnósticos alternativos", True),
                (1, "Ecografía renal", "Sin radiación; muestra hidronefrosis, pero deja pasar cálculos ureterales pequeños", False),
                (2, "Radiografía simple de abdomen", "Solo cálculos radioopacos; sensibilidad de 50 a 60 %", False),
                (2, "Pielografía retrógrada", "Invasiva; se usa en el tratamiento, no para el diagnóstico inicial", False),
                (2, "Cistoscopía", "Examina la vejiga; no es un estudio de cólico", False)],
         veredicto=("Sospecha de urolitiasis en el adulto = tomografía sin contraste", "La ecografía es la primera opción en la embarazada y el niño.")))

# 041 · REGLA · cáncer de próstata Gleason 6 en el anciano
