# 042 · CUADRO · cálculos en múltiples cálices
S("cuadro", "RM-NEF-042", "Cálculos en múltiples cálices (carga litiásica grande): nefrolitotomía percutánea",
  "Urología · tratamiento de la litiasis renal",
  ("Tratamiento de la litiasis renal", ["Depende de la carga litiásica, la localización, la composición y la anatomía.", "Los cálculos pequeños admiten litotripsia o ureteroscopía."]),
  ("Pregunta de tratamiento", ["¿Cuál es el tratamiento más recomendado si los cálculos están en múltiples cálices?"]),
  ["Cálculo de menos de 2 cm: litotripsia extracorpórea por ondas de choque o ureteroscopía flexible con láser.",
   "Cálculos múltiples en varios cálices, mayores de 2 cm o coraliformes: nefrolitotomía percutánea (nefroscopía percutánea), con las mayores tasas de pacientes libres de cálculos en pocas sesiones.",
   "La litotripsia extracorpórea rinde poco en cálculos grandes, inferiores o de cuello calicial estrecho, y deja fragmentos que pueden obstruir.",
   "Alerta: esterilizar la orina con urocultivo antes de la cirugía; la sepsis y el sangrado son las complicaciones más temidas. La nefrectomía solo en riñón destruido sin función."],
  "EAU, Guía de urolitiasis (edición 2025); " + CW + ".",
  op=("¿Tratamiento más recomendado?", ["Sí: permite extraer gran carga litiásica", "No: excepcional hoy", "No: rinde poco en cálculos grandes", "No: solo en riñón destruido sin función", "No: indicada en cálculos pequeños, no en gran carga"],
      {0: "Nefroscopía percutánea", 1: "Nefrostomía abierta", 2: "Litotripsia extracorpórea", 3: "Nefrectomía total", 4: "Ureteroscopía retrógrada"}),
  d=dict(veredicto=("Cálculos en múltiples cálices = nefrolitotomía percutánea", "Litotripsia y ureteroscopía sirven en cálculos pequeños; la cirugía abierta y la nefrectomía son excepcionales.")),
  clasif=dict(titulo="Elección del tratamiento según la carga litiásica", cols=["Situación", "Tratamiento preferido", "Comentario"],
              filas=[["Cálculo renal de menos de 2 cm", "Litotripsia extracorpórea o ureteroscopía flexible con láser", "Menos invasivos; la litotripsia rinde menos en polo inferior"],
                     ["Varios cálices", "Nefrolitotomía percutánea", "Se accede al sistema colector por la región lumbar y se extraen los cálculos"],
                     ["Cálculo mayor de 2 cm o coraliforme", "Nefrolitotomía percutánea", "Mayor tasa de pacientes libres de cálculos"],
                     ["Riñón destruido sin función", "Nefrectomía", "Excepcional; la nefrostomía abierta casi no se usa"]], caso=1, ancho_primera=260,
              nota="Antes de operar se esteriliza la orina según el urocultivo."))

# 043 · ÁRBOL · hematuria tras traumatismo cerrado
S("arbol", "RM-NEF-043", "Hematuria tras traumatismo cerrado en paciente estable: tomografía con contraste y fase tardía",
  "Trauma urológico · hematuria postraumática",
  ("Hematuria tras traumatismo cerrado", ["La hematuria franca indica lesión del tracto urinario hasta demostrar lo contrario.", "Puede venir del riñón, el uréter, la vejiga o la uretra."]),
  ("Varón de 35 años", ["Caída de moto, hemodinámicamente estable.", "Hematuria desde hace 2 horas. ¿Qué se solicita para definir la lesión?"]),
  ["Estable: tomografía de abdomen y pelvis con contraste intravenoso y fase tardía (urográfica); gradúa el trauma renal con la escala AAST (I a V) y muestra extravasación, sangrado y lesiones vasculares.",
   "Fractura pélvica o sospecha de lesión vesical: agregar cistografía por tomografía con la vejiga llena. Inestable: se opera sin imágenes.",
   "La ecografía detecta líquido libre pero no gradúa; la radiografía simple y la gammagrafía no aportan; el lavado peritoneal casi no se usa.",
   "Alerta: sangre en el meato, no pasar sonda hasta descartar lesión uretral con uretrografía retrógrada. La mayoría de los traumas renales se maneja de forma conservadora."],
  "AUA, Urotrauma Guideline 2020 (J Urol 2021); " + CW + ".",
  op=("¿Qué solicitaría?", ["Sí: define y gradúa la lesión", "No: no gradúa la lesión", "No: no aporta", "No: no aporta", "No: casi no se usa"],
      {0: "Tomografía", 1: "Ecografía", 2: "Radiografía simple", 3: "Gammagrafía", 4: "Lavado peritoneal"}),
  arbol=Q("Hematuria tras traumatismo cerrado", [
      L("Hemodinámicamente inestable", "LAPAROTOMÍA", ["Se opera sin imágenes previas", "Control del sangrado"]),
      L("Estable (este caso)", "TOMOGRAFÍA", ["Contraste intravenoso y fase tardía", "Gradúa la lesión con la escala AAST"], path=True),
      L("Fractura pélvica o sospecha de lesión vesical", "CISTOGRAFÍA", ["Por tomografía, con la vejiga llena", "Si hay sangre en el meato: uretrografía antes de sondar"])], path=True),
  clasif=dict(titulo="Escala AAST del trauma renal (revisión 2018)", cols=["Grado", "Lesión"],
              filas=[["I", "Contusión o hematoma subcapsular no expansivo, sin laceración"],
                     ["II", "Hematoma perirrenal confinado o laceración parenquimatosa menor de 1 cm, sin extravasación de orina"],
                     ["III", "Laceración parenquimatosa de más de 1 cm, sin rotura del sistema colector"],
                     ["IV", "Laceración que llega al sistema colector con extravasación de orina, o lesión vascular segmentaria con sangrado o infarto"],
                     ["V", "Riñón fragmentado, o lesión o avulsión del pedículo renal con devascularización"]], caso=None, ancho_primera=70,
              nota="La mayoría se maneja de forma conservadora, con reposo, vigilancia y embolización si hay sangrado."))

# 044 · EMBUDO · pielonefritis aguda
